using System;
using System.Collections.Generic;
using System.IO;
using System.Text;
using System.Xml;
using System.Net;
using System.Security.Cryptography;
using System.Threading;
public sealed class NewsItem { public string Id,Kind,Title,Body; public DateTime Date; public string Fingerprint {get{return NewsFeed.Hash(Id+"\n"+Kind+"\n"+Title+"\n"+Body+"\n"+Date.ToString("o"));}} }
public static class NewsFeed {
 public const int MaxBytes=131072;
 public static string Hash(string value){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(Encoding.UTF8.GetBytes(value))).Replace("-","");}
 public static Uri Endpoint(string text){Uri u;if(!Uri.TryCreate(text,UriKind.Absolute,out u)||u.Scheme!="https"||!u.IsDefaultPort||u.UserInfo.Length>0||u.Query.Length>0||u.Fragment.Length>0||(u.Host!="raw.githubusercontent.com"&&u.Host!="raiinman.github.io")||(u.Host=="raw.githubusercontent.com"&&!u.AbsolutePath.StartsWith("/raiinman/",StringComparison.Ordinal)))throw new InvalidDataException("Invalid publisher endpoint");return u;}
 static string Text(XmlElement e,string name,int max){var n=e.SelectSingleNode(name) as XmlElement;if(n==null||n.ChildNodes.Count!=1||n.FirstChild.NodeType!=XmlNodeType.Text||String.IsNullOrWhiteSpace(n.InnerText)||n.InnerText.Length>max)throw new InvalidDataException("Invalid field");return n.InnerText;}
 public static List<NewsItem> Parse(string xml){if(Encoding.UTF8.GetByteCount(xml)>MaxBytes)throw new InvalidDataException("Feed too large");var d=new XmlDocument{XmlResolver=null};using(var r=XmlReader.Create(new StringReader(xml),new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=MaxBytes}))d.Load(r);var root=d.DocumentElement;if(root==null||root.Name!="news"||root.GetAttribute("version")!="1")throw new InvalidDataException("Unknown schema");var result=new List<NewsItem>();var ids=new HashSet<string>();foreach(XmlNode n in root.ChildNodes){var e=n as XmlElement;if(e==null)continue;if(e.Name!="item"||result.Count>=50)throw new InvalidDataException("Invalid items");var id=e.GetAttribute("id");if(id.Length<1||id.Length>80||!ids.Add(id))throw new InvalidDataException("Invalid id");var kind=e.GetAttribute("kind");if(kind!="announcement"&&kind!="changelog"&&kind!="update")throw new InvalidDataException("Invalid kind");DateTime date;if(!DateTime.TryParseExact(e.GetAttribute("date"),"yyyy-MM-ddTHH:mm:ssZ",System.Globalization.CultureInfo.InvariantCulture,System.Globalization.DateTimeStyles.AdjustToUniversal|System.Globalization.DateTimeStyles.AssumeUniversal,out date))throw new InvalidDataException("Invalid date");result.Add(new NewsItem{Id=id,Kind=kind,Date=date,Title=Text(e,"title",140),Body=Text(e,"body",4000)});}result.Sort(delegate(NewsItem a,NewsItem b){int order=b.Date.CompareTo(a.Date);return order!=0?order:String.CompareOrdinal(a.Id,b.Id);});return result;}
 public static string ReadBounded(Stream stream){using(var m=new MemoryStream()){var b=new byte[4096];int n;while((n=stream.Read(b,0,b.Length))>0){if(m.Length+n>MaxBytes)throw new InvalidDataException("Feed too large");m.Write(b,0,n);}return new UTF8Encoding(false,true).GetString(m.ToArray());}}
 public static string Fetch(string endpoint){var uri=Endpoint(endpoint);var req=(HttpWebRequest)WebRequest.Create(uri);req.AllowAutoRedirect=false;req.UseDefaultCredentials=false;req.Credentials=null;req.CookieContainer=null;req.Proxy=null;req.Timeout=8000;req.ReadWriteTimeout=8000;req.UserAgent="FlutterDeck-News/1";using(var timer=new Timer(delegate{req.Abort();},null,8000,Timeout.Infinite)){using(var response=(HttpWebResponse)req.GetResponse()){if(response.StatusCode!=HttpStatusCode.OK||response.ContentLength>MaxBytes)throw new InvalidDataException("Unexpected feed response");using(var stream=response.GetResponseStream()){var xml=ReadBounded(stream);Parse(xml);return xml;}}}}
 public static string Folder(string endpoint){return Path.Combine(DeckPaths.Root,"news",Hash(endpoint));}
 public static string LoadCache(string folder){var path=Path.Combine(folder,"cache.xml");if(!File.Exists(path))return null;using(var s=File.OpenRead(path)){var xml=ReadBounded(s);Parse(xml);return xml;}}
 public static void SaveCache(string folder,string xml){Parse(xml);Write(folder,"cache.xml",xml);}
 public static HashSet<string> LoadRead(string folder){var result=new HashSet<string>();var path=Path.Combine(folder,"read.txt");if(!File.Exists(path))return result;if(new FileInfo(path).Length>8192)throw new InvalidDataException("Read state too large");foreach(var line in File.ReadAllLines(path)){if(line.Length!=64)throw new InvalidDataException("Invalid read state");foreach(char c in line)if(!Uri.IsHexDigit(c))throw new InvalidDataException("Invalid read state");result.Add(line);}return result;}
 public static void SaveRead(string folder,List<NewsItem> items){var lines=new List<string>();foreach(var item in items)lines.Add(item.Fingerprint);Write(folder,"read.txt",String.Join("\n",lines));}
 static void Write(string folder,string name,string value){Directory.CreateDirectory(folder);var path=Path.Combine(folder,name);var tmp=path+".tmp";File.WriteAllText(tmp,value,new UTF8Encoding(false));if(File.Exists(path))File.Replace(tmp,path,path+".bak");else File.Move(tmp,path);}
}
